/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * Three.js engine for the public 3D concept model of New Kikwite Town.
 * Data comes from /public/explore (generated by tools/concept-model).
 * The public model has no satellite photo, no site boundary line and no
 * neighbouring buildings; zone edges on the outside of the site are feathered.
 */
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { ZONE_SHORT } from "@/lib/content/zones";

export interface Zone {
  id: string;
  name: string;
  acres: number;
  phase: number;
  color: string;
  polys: { o: number[][]; h: number[][][] }[];
  label: [number, number];
}

export interface Explorer {
  zones: Zone[];
  setPhase(p: number, animate?: boolean): void;
  select(id: string | null, fly?: boolean): void;
  overview(ms?: number): void;
  showLabels(on: boolean): void;
  onPick(fn: (z: Zone | null) => void): void;
  /** Frame a named view instantly and hide labels, for still renders. */
  shot(view: string): void;
  /**
   * Render one frame of the "land becomes the town" film, for offline frame export.
   * f runs 0 (today) to 3 (all phases built) and may be fractional; a runs 0 to 1 along the camera path.
   */
  film(f: number, a: number, zoom?: number): void;
  dispose(): void;
}

const EXAG = 1.5;
const KIND: Record<string, number> = {
  hospital: 0xf4f1ec, library: 0xc98f5a, museum: 0xd8b48a, commercial: 0xe7d7ef, hotel: 0xf3e3bd, villa: 0xf6efe0,
  apartment: 0xf2e8d8, townhouse: 0xe9d3b1, university: 0xdfe4fb, warehouse: 0xcfd2c6, barn: 0xb5532f, processing: 0xe8e2cf,
  visitor: 0xd6c3a0, lodge: 0x8a6a45, cabin: 0x9b7a52, substation: 0xb7c0c8, clubhouse: 0xf1ead8,
  hut: 0xc7a46a, silo: 0xdedfd8, biogas: 0x8fa36a, tower: 0x8a6a45, watertower: 0xd8dde2,
};

function hexA(hex: string, a: number) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}
function pip(x: number, y: number, ring: number[][]) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1], xj = ring[j][0], yj = ring[j][1];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

export async function createExplorer(
  canvas: HTMLCanvasElement,
  labelsEl: HTMLElement,
  opts: { base: string; sky: string; small: boolean; reduceMotion: boolean },
): Promise<Explorer> {
  const [ctx, plan, groundImg] = await Promise.all([
    fetch(`${opts.base}/context.json`).then((r) => r.json()),
    fetch(`${opts.base}/plan.json`).then((r) => r.json()),
    new Promise<HTMLImageElement>((res, rej) => {
      const im = new Image();
      im.decoding = "async";
      // Decode off the main thread before the image is drawn, so drawImage does not decode it synchronously.
      im.onload = () => (im.decode ? im.decode().catch(() => undefined) : Promise.resolve()).then(() => res(im));
      im.onerror = rej;
      im.src = `${opts.base}/ground.webp`;
    }),
  ]);
  const F = ctx.frame, HW: number = F.half_w, HH: number = F.half_h, N: number = ctx.dem.n;
  const DEM = new Float32Array(N * N);
  let mn = Infinity;
  ctx.dem.dm.forEach((row: number[], i: number) => row.forEach((v, j) => { DEM[i * N + j] = v; if (v < mn) mn = v; }));
  const BASE = mn / 10;
  const zones: Zone[] = plan.zones;

  const hAt = (x: number, y: number) => {
    const fx = ((x + HW) / (2 * HW)) * (N - 1), fy = ((HH - y) / (2 * HH)) * (N - 1);
    let x0 = Math.floor(fx), y0 = Math.floor(fy);
    x0 = Math.min(Math.max(x0, 0), N - 2); y0 = Math.min(Math.max(y0, 0), N - 2);
    const tx = Math.min(Math.max(fx - x0, 0), 1), ty = Math.min(Math.max(fy - y0, 0), 1);
    const a = DEM[y0 * N + x0], b = DEM[y0 * N + x0 + 1], c = DEM[(y0 + 1) * N + x0], d = DEM[(y0 + 1) * N + x0 + 1];
    return (((a * (1 - tx) + b * tx) * (1 - ty) + (c * (1 - tx) + d * tx) * ty) / 10 - BASE) * EXAG;
  };

  // ---------- renderer ----------
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, opts.small ? 1.5 : 2));
  const S = Math.min(opts.small ? 2048 : 4096, renderer.capabilities.maxTextureSize);
  const K = S / (2 * HW);
  const cx = (x: number) => ((x + HW) / (2 * HW)) * S;
  const cy = (y: number) => ((HH - y) / (2 * HH)) * S;
  const scene = new THREE.Scene();
  const setSky = (c: string) => {
    const col = new THREE.Color(c);
    scene.background = col;
    scene.fog = new THREE.Fog(col, 7000, 17000);
  };
  setSky(opts.sky);
  const camera = new THREE.PerspectiveCamera(38, 1, 5, 40000);
  scene.add(new THREE.HemisphereLight(0xf3f6ff, 0x5d5140, 2.4));
  const sun = new THREE.DirectionalLight(0xfff1dc, 2.1);
  sun.position.set(-3000, 5000, -2000);
  scene.add(sun);

  // ---------- terrain ----------
  const texCanvas = document.createElement("canvas");
  texCanvas.width = texCanvas.height = S;
  const tex = new THREE.CanvasTexture(texCanvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const tgeo = new THREE.PlaneGeometry(2 * HW, 2 * HH, N - 1, N - 1);
  tgeo.rotateX(-Math.PI / 2);
  const pos = tgeo.attributes.position;
  for (let i = 0; i < pos.count; i++) pos.setY(i, (DEM[i] / 10 - BASE) * EXAG);
  tgeo.computeVertexNormals();
  const terrain = new THREE.Mesh(tgeo, new THREE.MeshLambertMaterial({ map: tex }));
  scene.add(terrain);
  {
    const depth = -70;
    const skirtMat = new THREE.MeshLambertMaterial({ color: 0x6b5a45, side: THREE.DoubleSide });
    const edges: [number, number][] = [];
    for (let j = 0; j < N; j++) edges.push([0, j]);
    for (let i = 1; i < N; i++) edges.push([i, N - 1]);
    for (let j = N - 2; j >= 0; j--) edges.push([N - 1, j]);
    for (let i = N - 2; i >= 0; i--) edges.push([i, 0]);
    const verts: number[] = [];
    for (const [i, j] of edges) {
      const x = -HW + (j * 2 * HW) / (N - 1), z = -HH + (i * 2 * HH) / (N - 1);
      verts.push(x, (DEM[i * N + j] / 10 - BASE) * EXAG, z, x, depth, z);
    }
    const idx: number[] = [];
    for (let k = 0; k < edges.length - 1; k++) { const a = 2 * k; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
    const sg = new THREE.BufferGeometry();
    sg.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
    sg.setIndex(idx);
    sg.computeVertexNormals();
    scene.add(new THREE.Mesh(sg, skirtMat));
    const base = new THREE.Mesh(new THREE.PlaneGeometry(2 * HW, 2 * HH), skirtMat);
    base.rotation.x = -Math.PI / 2;
    base.position.y = depth;
    scene.add(base);
  }

  // ---------- painting ----------
  const ring = (g: CanvasRenderingContext2D, r: number[][]) => {
    r.forEach((q, i) => (i ? g.lineTo(cx(q[0]), cy(q[1])) : g.moveTo(cx(q[0]), cy(q[1]))));
    g.closePath();
  };
  const zonePath = (g: CanvasRenderingContext2D, z: Zone) => {
    g.beginPath();
    for (const p of z.polys) { ring(g, p.o); for (const h of p.h) ring(g, h); }
  };
  const line = (g: CanvasRenderingContext2D, pts: number[][]) => {
    g.beginPath();
    pts.forEach((q, i) => (i ? g.lineTo(cx(q[0]), cy(q[1])) : g.moveTo(cx(q[0]), cy(q[1]))));
  };
  const stripes = (g: CanvasRenderingContext2D, r: number[][], angle: number, spacing: number, color: string, width: number) => {
    g.save(); g.beginPath(); ring(g, r); g.clip();
    const xs = r.map((q) => q[0]), ys = r.map((q) => q[1]);
    const mx = (Math.min(...xs) + Math.max(...xs)) / 2, my = (Math.min(...ys) + Math.max(...ys)) / 2;
    const R = Math.hypot(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys));
    const ca = Math.cos(angle), sa = Math.sin(angle);
    g.strokeStyle = color; g.lineWidth = Math.max(1, width * K);
    for (let v = -R; v <= R; v += spacing) {
      g.beginPath();
      g.moveTo(cx(mx - R * ca - v * sa), cy(my - R * sa + v * ca));
      g.lineTo(cx(mx + R * ca - v * sa), cy(my + R * sa + v * ca));
      g.stroke();
    }
    g.restore();
  };

  const baseCanvas = document.createElement("canvas");
  baseCanvas.width = baseCanvas.height = S;
  {
    const g = baseCanvas.getContext("2d")!;
    g.drawImage(groundImg, 0, 0, S, S);
    g.lineCap = "round"; g.lineJoin = "round";
    const styles: [number, string][] = [[0, ""], [5, "rgba(244, 238, 224, 0.85)"], [10, "rgba(250, 230, 168, 0.95)"]];
    for (const cls of [1, 2]) {
      g.strokeStyle = styles[cls][1]; g.lineWidth = Math.max(1, styles[cls][0] * K);
      for (const r of ctx.roads) if (r.c === cls) { line(g, r.p); g.stroke(); }
    }
  }
  // soft mask: the union of all zones, blurred, so the site's outer edge reads as a concept, not a survey line
  const maskCanvas = document.createElement("canvas");
  maskCanvas.width = maskCanvas.height = S;
  {
    const g = maskCanvas.getContext("2d")!;
    g.filter = `blur(${Math.round(55 * K)}px)`;
    g.fillStyle = "#000";
    for (const z of zones) { zonePath(g, z); g.fill("evenodd"); }
    g.filter = "none";
    for (const z of zones) { const shrink = z; zonePath(g, shrink); }
  }
  const layer = document.createElement("canvas");
  layer.width = layer.height = S;

  let phase = 3;
  let phaseF = 3; // fractional phase used by the film; equals phase in normal use
  let ovl = 1; // strength of the not-yet-built plan overlay
  let selected: Zone | null = null;
  const liveAmt = (ph: number) => (ph <= 0 ? 1 : Math.max(0, Math.min(1, phaseF - (ph - 1))));

  function paint() {
    const L = layer.getContext("2d")!;
    L.clearRect(0, 0, S, S);
    L.lineCap = "round"; L.lineJoin = "round";
    for (const z of zones) {
      const a = liveAmt(z.phase);
      const mix = (off: number, on: number) => off * ovl + (on - off * ovl) * a;
      zonePath(L, z);
      if (z.id === "forest") L.fillStyle = hexA(z.color, mix(0.16, 0.32));
      else if (z.id === "wetland") L.fillStyle = hexA("#3f8f9a", 0.6);
      else L.fillStyle = hexA(z.color, mix(0.2, 0.62));
      L.fill("evenodd");
      L.strokeStyle = `rgba(255,255,255,${(0.75 * Math.max(a, ovl)).toFixed(3)})`; L.lineWidth = Math.max(1, 2.5 * K);
      L.setLineDash(a >= 0.999 ? [] : [10 * K, 7 * K]); L.stroke(); L.setLineDash([]);
    }
    const wz = zones.find((z) => z.id === "wetland");
    if (wz) for (const p of wz.polys) stripes(L, p.o, 0.6, 26, "rgba(190, 230, 232, 0.4)", 5);
    for (const f of plan.paint) {
      const fa = liveAmt(f.ph);
      if (fa <= 0) continue;
      L.globalAlpha = fa;
      if (f.t === "golf") {
        L.strokeStyle = "rgba(150, 200, 96, 0.95)"; L.lineWidth = 34 * K;
        for (const h of f.holes) { line(L, h); L.stroke(); }
        for (const h of f.holes) {
          const e = h[1];
          L.fillStyle = "#c6ee8c"; L.beginPath(); L.arc(cx(e[0]), cy(e[1]), 15 * K, 0, 7); L.fill();
          L.fillStyle = "#efe3b4"; L.beginPath(); L.ellipse(cx(e[0]) + 16 * K, cy(e[1]) + 10 * K, 7 * K, 4 * K, 0.5, 0, 7); L.fill();
          const s = h[0]; L.fillStyle = "#b9e07c"; L.fillRect(cx(s[0]) - 5 * K, cy(s[1]) - 5 * K, 10 * K, 10 * K);
        }
      } else if (f.t === "solar") {
        L.fillStyle = "rgba(60, 70, 80, 0.35)"; L.beginPath(); ring(L, f.p); L.fill();
        stripes(L, f.p, f.a, f.s, "rgba(36, 58, 92, 0.95)", 4.2);
      } else if (f.t === "rows") {
        stripes(L, f.p, f.a, f.s, hexA(f.c, 0.75), 3.5);
      } else if (f.t === "circuit") {
        L.strokeStyle = "rgba(70, 70, 72, 0.95)"; L.lineWidth = 13 * K; line(L, f.p); L.closePath(); L.stroke();
        L.strokeStyle = "rgba(255, 255, 255, 0.8)"; L.lineWidth = 1.2 * K; L.setLineDash([6 * K, 6 * K]); L.stroke(); L.setLineDash([]);
      } else if (f.t === "fence") {
        L.strokeStyle = "rgba(240, 200, 120, 0.95)"; L.lineWidth = 3 * K; L.setLineDash([9 * K, 6 * K]);
        line(L, f.p); L.closePath(); L.stroke(); L.setLineDash([]);
      } else if (f.t === "boardwalk") {
        L.strokeStyle = "rgba(130, 94, 58, 0.95)"; L.lineWidth = 4 * K; line(L, f.p); L.stroke();
      }
      L.globalAlpha = 1;
    }
    for (const r of plan.roads) {
      line(L, r.p);
      const ra = liveAmt(r.ph);
      if (ra > 0) {
        L.globalAlpha = ra;
        L.strokeStyle = "rgba(90, 84, 72, 0.9)"; L.lineWidth = 12 * K; L.stroke();
        L.strokeStyle = "rgba(226, 220, 204, 0.98)"; L.lineWidth = 9 * K; L.stroke();
        L.globalAlpha = 1;
      }
      if (ra < 1) {
        L.strokeStyle = `rgba(240, 236, 224, ${(0.75 * ovl * (1 - ra)).toFixed(3)})`; L.lineWidth = 3 * K; L.setLineDash([8 * K, 8 * K]); L.stroke(); L.setLineDash([]);
      }
    }
    if (selected) {
      zonePath(L, selected);
      L.strokeStyle = "rgba(255, 255, 255, 0.95)"; L.lineWidth = 8 * K; L.stroke();
      L.strokeStyle = selected.color; L.lineWidth = 4 * K; L.stroke();
    }
    // feather the outside edge of the site
    L.globalCompositeOperation = "destination-in";
    L.drawImage(maskCanvas, 0, 0);
    L.globalCompositeOperation = "source-over";
    const g = texCanvas.getContext("2d")!;
    g.drawImage(baseCanvas, 0, 0);
    g.drawImage(layer, 0, 0);
    tex.needsUpdate = true;
  }

  // ---------- 3D content ----------
  const UP = new THREE.Vector3(0, 1, 0);
  const instanced = (geo: THREE.BufferGeometry, mat: THREE.Material, items: any[], place: (it: any, p: THREE.Vector3, q: THREE.Quaternion, s: THREE.Vector3, c: THREE.Color) => void) => {
    const mesh = new THREE.InstancedMesh(geo, mat, items.length);
    const base: { p: THREE.Vector3; q: THREE.Quaternion; s: THREE.Vector3 }[] = [];
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3(), col = new THREE.Color();
    items.forEach((it, i) => {
      place(it, p, q, s, col);
      m.compose(p, q, s); mesh.setMatrixAt(i, m); mesh.setColorAt(i, col);
      base.push({ p: p.clone(), q: q.clone(), s: s.clone() });
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.userData.base = base;
    return mesh;
  };
  const mat = new THREE.MeshLambertMaterial();
  const boxGeo = new THREE.BoxGeometry(1, 1, 1); boxGeo.translate(0, 0.5, 0);
  const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 18); cylGeo.translate(0, 0.5, 0);
  const coneGeo = new THREE.ConeGeometry(1, 1, 18); coneGeo.translate(0, 0.5, 0);
  const domeGeo = new THREE.SphereGeometry(1, 18, 10, 0, Math.PI * 2, 0, Math.PI / 2);
  const crown = new THREE.IcosahedronGeometry(1, 0); crown.translate(0, 1, 0);
  const bamGeo = new THREE.ConeGeometry(1, 1, 6); bamGeo.translate(0, 0.5, 0);
  const greens = [0x2f5a2c, 0x3b6b32, 0x284f27, 0x46733a, 0x335f30];

  function buildArena(a: any) {
    const g = new THREE.Group();
    const wall = new THREE.MeshLambertMaterial({ color: 0xf0ece4, side: THREE.DoubleSide });
    const seats = new THREE.MeshLambertMaterial({ color: 0xe0773a, side: THREE.DoubleSide });
    const pitchMat = new THREE.MeshLambertMaterial({ color: 0x5ea64a });
    const outer = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.04, 1, 64, 1, true), wall);
    outer.scale.set(a.rx, a.h + 6, a.ry); outer.position.y = (a.h + 6) / 2 - 6;
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(1, 0.62, 1, 64, 1, true), seats);
    bowl.scale.set(a.rx * 0.97, a.h * 0.85, a.ry * 0.97); bowl.position.y = (a.h * 0.85) / 2 + 1;
    const roof = new THREE.Mesh(new THREE.RingGeometry(0.72, 1.04, 64), wall);
    roof.rotation.x = -Math.PI / 2; roof.scale.set(a.rx, a.ry, 1); roof.position.y = a.h + 0.2;
    const pitch = new THREE.Mesh(new THREE.CircleGeometry(1, 48), pitchMat);
    pitch.rotation.x = -Math.PI / 2; pitch.scale.set(a.rx * 0.58, a.ry * 0.56, 1); pitch.position.y = 1.4;
    g.add(outer, bowl, roof, pitch);
    g.position.set(a.x, hAt(a.x, a.y), -a.y); g.rotation.y = a.a;
    g.userData.arena = true;
    return g;
  }

  const groups: THREE.Group[] = [];
  for (let k = 0; k < 4; k++) {
    const grp = new THREE.Group();
    grp.userData.t = 1;
    const bx = plan.boxes.filter((b: any) => b[7] === k);
    if (bx.length) grp.add(instanced(boxGeo, mat, bx, (b, p, q, s, c) => {
      const h0 = hAt(b[0], b[1]);
      const slope = Math.max(Math.abs(hAt(b[0] + b[2] / 2, b[1]) - h0), Math.abs(hAt(b[0], b[1] + b[3] / 2) - h0));
      p.set(b[0], h0 - slope - 0.5, -b[1]); q.setFromAxisAngle(UP, b[5]); s.set(b[2], b[4] + slope + 0.5, b[3]);
      c.setHex(KIND[b[6]] ?? 0xeeeeee);
    }));
    const cy_ = plan.cyl.filter((c: any) => c[5] === k);
    const solids = cy_.filter((c: any) => c[6] === 0 || c[6] === 1);
    if (solids.length) grp.add(instanced(cylGeo, mat, solids, (c, p, q, s, col) => {
      p.set(c[0], hAt(c[0], c[1]) - 0.5, -c[1]); q.identity(); s.set(c[2], c[3] + 0.5, c[2]); col.setHex(KIND[c[4]] ?? 0xdddddd);
    }));
    const roofs = cy_.filter((c: any) => c[6] === 1);
    if (roofs.length) grp.add(instanced(coneGeo, mat, roofs, (c, p, q, s, col) => {
      p.set(c[0], hAt(c[0], c[1]) + c[3], -c[1]); q.identity(); s.set(c[2] * 1.25, c[2] * 0.9, c[2] * 1.25); col.setHex(0x8c6a3c);
    }));
    const domes = cy_.filter((c: any) => c[6] === 2);
    if (domes.length) grp.add(instanced(domeGeo, mat, domes, (c, p, q, s, col) => {
      p.set(c[0], hAt(c[0], c[1]), -c[1]); q.identity(); s.set(c[2], c[3], c[2]); col.setHex(KIND.biogas);
    }));
    const tr = plan.trees.filter((t: any) => t[4] === k);
    const broad = tr.filter((t: any) => t[3] !== 1), bam = tr.filter((t: any) => t[3] === 1);
    if (broad.length) grp.add(instanced(crown, mat, broad, (t, p, q, s, col) => {
      const r = (t[3] === 2 ? 4.2 : 6.2) * t[2];
      p.set(t[0], hAt(t[0], t[1]) + 1.5, -t[1]); q.setFromAxisAngle(UP, (t[0] * 13 + t[1] * 7) % 6.28);
      s.set(r, r * 0.95, r); col.setHex(t[3] === 2 ? 0x5f8f43 : greens[Math.abs(Math.round(t[0] + t[1])) % greens.length]);
    }));
    if (bam.length) grp.add(instanced(bamGeo, mat, bam, (t, p, q, s, col) => {
      p.set(t[0], hAt(t[0], t[1]), -t[1]); q.identity(); s.set(2.6 * t[2], 11 * t[2], 2.6 * t[2]); col.setHex(0x9cc45a);
    }));
    if (plan.arena && plan.arena.ph === k) grp.add(buildArena(plan.arena));
    groups.push(grp);
    scene.add(grp);
  }
  const applyRise = (g: THREE.Group) => {
    const e = 1 - Math.pow(1 - g.userData.t, 3);
    const m = new THREE.Matrix4(), s = new THREE.Vector3();
    g.children.forEach((mesh: any) => {
      if (mesh.isInstancedMesh) {
        mesh.userData.base.forEach((b: any, i: number) => { s.copy(b.s); s.y *= Math.max(0.001, e); m.compose(b.p, b.q, s); mesh.setMatrixAt(i, m); });
        mesh.instanceMatrix.needsUpdate = true;
      } else if (mesh.userData.arena) mesh.scale.y = Math.max(0.001, e);
    });
  };

  // ---------- labels ----------
  type Lbl = { el: HTMLElement; v: THREE.Vector3; zone?: Zone; w?: number; h?: number };
  const labels: Lbl[] = [];
  const placed: number[][] = [];
  let pickFn: (z: Zone | null) => void = () => {};
  const addLabel = (text: string, x: number, y: number, cls: string, zone?: Zone) => {
    const el = document.createElement(zone ? "button" : "div");
    el.className = `xlbl ${cls}`;
    if (zone) {
      (el as HTMLButtonElement).type = "button";
      el.style.setProperty("--dot", zone.color);
      el.addEventListener("click", () => pickFn(zone));
    }
    el.textContent = text;
    labelsEl.appendChild(el);
    labels.push({ el, v: new THREE.Vector3(x, hAt(x, y) + (zone ? 22 : 14), -y), zone });
  };
  for (const z of zones) addLabel(ZONE_SHORT[z.id] ?? z.name, z.label[0], z.label[1], "zone", z);
  for (const l of ctx.landmarks) addLabel(l.n, l.x, l.y, "mark");

  // ---------- camera ----------
  const controls = new OrbitControls(camera, canvas);
  controls.enableDamping = true; controls.dampingFactor = 0.08;
  controls.maxPolarAngle = 1.38; controls.minDistance = 120; controls.maxDistance = 11000;
  controls.screenSpacePanning = false;
  let flight: any = null;
  const flyTo = (t: THREE.Vector3, p: THREE.Vector3, ms: number) => {
    if (opts.reduceMotion || !ms) { controls.target.copy(t); camera.position.copy(p); controls.update(); return; }
    flight = { t0: performance.now(), ms, fromT: controls.target.clone(), fromP: camera.position.clone(), toT: t, toP: p };
  };
  const all = zones.flatMap((z) => z.polys.flatMap((p) => p.o));
  const minX = Math.min(...all.map((q) => q[0])), maxX = Math.max(...all.map((q) => q[0]));
  const minY = Math.min(...all.map((q) => q[1])), maxY = Math.max(...all.map((q) => q[1]));
  const overviewView = (): [THREE.Vector3, THREE.Vector3] => {
    const mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
    const narrow = canvas.clientWidth < 700;
    const t = new THREE.Vector3(mx, hAt(mx, my), -my - (narrow ? 250 : 450));
    if (narrow) { const d = 7600; return [t, t.clone().add(new THREE.Vector3(-0.12 * d, 0.86 * d, -0.5 * d))]; }
    const d = 4700;
    return [t, t.clone().add(new THREE.Vector3(-0.42 * d, 0.6 * d, -0.68 * d))];
  };
  const zoneView = (z: Zone): [THREE.Vector3, THREE.Vector3] => {
    const t = new THREE.Vector3(z.label[0], hAt(z.label[0], z.label[1]), -z.label[1]);
    const d = Math.max(1350, Math.sqrt(z.acres * 4046.86) * 3.2);
    return [t, t.clone().add(new THREE.Vector3(-0.35 * d, 0.62 * d, -0.78 * d))];
  };

  // ---------- picking ----------
  const ray = new THREE.Raycaster(), ndc = new THREE.Vector2();
  let down: [number, number] | null = null;
  const onDown = (e: PointerEvent) => { down = [e.clientX, e.clientY]; };
  const onUp = (e: PointerEvent) => {
    if (!down || Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 5) return;
    const r = canvas.getBoundingClientRect();
    ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
    ray.setFromCamera(ndc, camera);
    const hit = ray.intersectObject(terrain)[0];
    if (!hit) return;
    const x = hit.point.x, y = -hit.point.z;
    const z = zones.find((zz) => zz.polys.some((p) => pip(x, y, p.o) && !p.h.some((h) => pip(x, y, h)))) ?? null;
    pickFn(z);
  };
  canvas.addEventListener("pointerdown", onDown);
  canvas.addEventListener("pointerup", onUp);

  // ---------- loop ----------
  let labelsOn = true;
  const tmp = new THREE.Vector3();
  const resize = () => {
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
    for (const l of labels) l.w = 0; // measure again: fonts or text size may have changed
  };
  document.fonts?.ready.then(() => { for (const l of labels) l.w = 0; });
  const ro = new ResizeObserver(resize);
  ro.observe(canvas);
  resize();
  let raf = 0, last = performance.now(), alive = true, frozen = false;
  const loop = (now: number) => {
    if (!alive) return;
    const dt = now - last; last = now;
    if (flight) {
      const t = Math.min(1, (now - flight.t0) / flight.ms), e = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      controls.target.lerpVectors(flight.fromT, flight.toT, e); camera.position.lerpVectors(flight.fromP, flight.toP, e);
      if (t >= 1) flight = null;
    }
    controls.target.x = Math.max(-HW, Math.min(HW, controls.target.x));
    controls.target.z = Math.max(-HH, Math.min(HH, controls.target.z));
    controls.update();
    if (!frozen) for (const g of groups) if (g.visible && g.userData.t < 1) { g.userData.t = Math.min(1, g.userData.t + dt / 900); applyRise(g); }
    renderer.render(scene, camera);
    const w = canvas.clientWidth, h = canvas.clientHeight, dist = camera.position.distanceTo(controls.target);
    // Labels are placed in order (zones first) and any that would overlap one already placed is hidden,
    // so names stay readable and each one is a clear tap target on small screens.
    placed.length = 0;
    for (const l of labels) {
      tmp.copy(l.v).project(camera);
      let vis = labelsOn && tmp.z < 1 && Math.abs(tmp.x) < 1.05 && Math.abs(tmp.y) < 1.05 && !(l.zone && dist > 9000);
      const x = ((tmp.x + 1) / 2) * w, y = ((1 - tmp.y) / 2) * h;
      if (vis) {
        if (!l.w) { l.el.style.display = ""; l.w = l.el.offsetWidth; l.h = l.el.offsetHeight; }
        const bw = l.w || 60, bh = l.h || 24;
        const box = [x - bw / 2 - 3, y - bh - 3, x + bw / 2 + 3, y + 3];
        if (placed.some((q) => box[0] < q[2] && box[2] > q[0] && box[1] < q[3] && box[3] > q[1])) vis = false;
        else placed.push(box);
      }
      l.el.style.display = vis ? "" : "none";
      if (vis) l.el.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) translate(-50%, -100%)`;
      if (l.zone) l.el.style.opacity = l.zone.phase <= phase ? "1" : "0.72";
    }
    raf = requestAnimationFrame(loop);
  };

  const api: Explorer = {
    zones,
    setPhase(p, animate = true) {
      phase = p; phaseF = p; ovl = 1; frozen = false;
      groups.forEach((g, k) => {
        const show = k <= p;
        if (show && !g.visible) { g.visible = true; g.userData.t = animate && !opts.reduceMotion ? 0 : 1; applyRise(g); }
        if (!show) g.visible = false;
      });
      paint();
    },
    select(id, fly = true) {
      selected = id ? zones.find((z) => z.id === id) ?? null : null;
      paint();
      if (fly) { const [t, p] = selected ? zoneView(selected) : overviewView(); flyTo(t, p, 1700); }
    },
    overview(ms = 1400) { const [t, p] = overviewView(); flyTo(t, p, ms); },
    showLabels(on) { labelsOn = on; },
    onPick(fn) { pickFn = fn; },
    shot(view) {
      labelsOn = false;
      const z = zones.find((zz) => zz.id === view);
      selected = z ?? null;
      paint();
      let t: THREE.Vector3, p: THREE.Vector3;
      if (z) {
        t = new THREE.Vector3(z.label[0], hAt(z.label[0], z.label[1]), -z.label[1]);
        const d = Math.max(850, Math.sqrt(z.acres * 4046.86) * 2.3);
        p = t.clone().add(new THREE.Vector3(-0.38 * d, 0.55 * d, -0.74 * d));
      } else {
        const mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
        t = new THREE.Vector3(mx, hAt(mx, my), -my);
        const d = view === "hero" ? 3300 : 4200;
        p = view === "hero"
          ? t.clone().add(new THREE.Vector3(0.5 * d, 0.38 * d, 0.78 * d))
          : t.clone().add(new THREE.Vector3(-0.42 * d, 0.6 * d, -0.68 * d));
      }
      flight = null; controls.target.copy(t); camera.position.copy(p); controls.update();
    },
    film(f, a, zoom = 1) {
      frozen = true; labelsOn = false; selected = null; flight = null;
      phaseF = Math.max(0, Math.min(3, f)); phase = Math.floor(phaseF + 1e-6); ovl = 0.28;
      paint();
      groups.forEach((g, k) => {
        const amt = k === 0 ? 1 : Math.max(0, Math.min(1, phaseF - (k - 1)));
        g.visible = amt > 0;
        g.userData.t = amt; applyRise(g);
      });
      const mx = (minX + maxX) / 2, my = (minY + maxY) / 2;
      const t = new THREE.Vector3(mx, hAt(mx, my), -my);
      const e = a * a * (3 - 2 * a);
      const yaw = Math.atan2(0.78, 0.5) + 0.36 - 0.46 * e;
      const d = (3150 - 800 * e) * zoom, up = 0.54 - 0.12 * e;
      const p = t.clone().add(new THREE.Vector3(Math.cos(yaw) * d, up * d, Math.sin(yaw) * d));
      controls.target.copy(t); camera.position.copy(p); controls.update();
      renderer.render(scene, camera);
    },
    dispose() {
      alive = false; cancelAnimationFrame(raf); ro.disconnect();
      canvas.removeEventListener("pointerdown", onDown); canvas.removeEventListener("pointerup", onUp);
      controls.dispose(); renderer.dispose(); labelsEl.innerHTML = "";
    },
  };
  (api as any).setSky = setSky;
  api.setPhase(3, false);
  const [t0, p0] = overviewView();
  flyTo(t0, p0, 0);
  raf = requestAnimationFrame(loop);
  return api;
}
